pseudocode.rxjs:
// merge is the one channel the three reviewers share.
ready$ = merge(criteria$, design$, consistency$).pipe(
  // Correlation: one group for each order a report names.
  groupBy((report) => report.order),
  mergeMap((order$) =>
    order$.pipe(
      // Completion condition: an order's set is complete at its third report.
      take(3),
      // Aggregation: gather the complete set's reports into one list.
      toArray(),
      // Aggregation: make that list one message, its findings added up.
      map(gather),
    ),
  ),
  // The complete set goes on one frame after the report that completed it.
  delay(1),
);

// Illustrative: an adapter's work is a call into an application that knows no streams, which a marble example could only fake; this is the shape the app's command feature gives it.
// the adapter listens on the channel for load
loaded$ = events.on(load).pipe(
  // a newer load cancels the call still in flight
  switchMap(() =>
    // the adapter calls the application through its own interface
    defer(() => boardApi.load()).pipe(
      // the application's reply becomes a message on the channel
      map((document) => loadSuccess(document)),
      // and so does its failure
      catchError((error) => of(loadFailure(toAppError(error)))),
    ),
  ),
);

// A session is free when it starts listening and again each time its work completes.
const finished$ = new Subject<string>();
const free$ = finished$.pipe(startWith('Session 1', 'Session 2', 'Session 3'));
// delay(1): the queue hands an order on no sooner than one step after it arrives.
const queued$ = orders$.pipe(delay(1));
// zip is the queue: it pairs the oldest waiting order with the oldest free session.
const taken$ = zip(queued$, free$).pipe(share());
// mergeMap is each consumer at work; endWith frees that session when its work completes.
taken$
  .pipe(mergeMap(([order, session]) => work(order).pipe(endWith(session))))
  .subscribe(finished$);

// filter is the delivery: a session receives only the orders paired with its name.
const takenBy = (session: string) =>
  taken$.pipe(
    filter(([, by]) => by === session),
    map(([order]) => order),
  );

const routed$ = findings$.pipe(
  // The router reads each finding's own fields and names its one route.
  map((finding) => ({ finding, route: routeOf(finding) })),
  // It sends the finding on one step after reading it.
  delay(1),
  // One decision per finding, however many channels are listening.
  share(),
);
const on = (route: Route) =>
  routed$.pipe(
    // A channel takes only the findings routed to it, unchanged.
    filter((routed) => routed.route === route),
    map((routed) => routed.finding),
  );
// The three routes; follow-up is the default for a finding no rule fits.
const blocking$ = on('blocking');
const operator$ = on('operator');
const followUp$ = on('follow-up');

// commandId(command) is the request id; commandId(result), copied from it, is the correlation id.
resumed$ = command$.pipe(
  // Each command is a pending request, with its own wait on the shared reply channel.
  mergeMap((command) =>
    // The match: the first result whose correlation id equals the request id ends the wait.
    result$.pipe(first((result) => commandId(result) === commandId(command))),
  ),
  // Not part of the pattern: a matched result is handed on a frame later, as a step of its own.
  delay(1),
);

// Illustrative: an event message is a kind of message, not an operator; this only maps the flow onto RxJS, and the copying and the age check belong to other patterns.
interface Transition {
  readonly order: number;
  readonly phase: string;
  // the event's time, most of what it says
  readonly at: number;
}

// the channel the lifecycle announces on, naming no reader
const transitions$ = new Subject<Transition>();
// the event message, sent as the change happens
const announce = (transition: Transition) => transitions$.next(transition);

// a subscriber decides for itself what the news means
transitions$.subscribe((transition) => quality.note(transition));
// another subscriber decides differently
transitions$.subscribe((transition) => intent.expect(transition));

// the beacon: replays the last announcement it was given, however old
const beacon$ = new ReplaySubject<Transition>(1);
// the beacon write, one more subscriber to the announcements
transitions$.subscribe((transition) => beacon$.next(transition));

const sweep = (now: number) =>
  beacon$.pipe(
    // the sweep reads whatever the beacon holds now
    take(1),
    // the age check: the reader judges expiry by its own clock
    map(({ at }) => (now - at >= staleAfter ? 'stale' : 'fresh')),
  );

handed$ = requests$.pipe(
  // the dispatcher reads each request on the frame after it arrives
  delay(1),
  // the dispatcher chooses the performer by the kind of work the request asks for
  groupBy((request) => roleOf(request)),
  // performers of different kinds work side by side
  mergeMap((role$) =>
    // a performer works on one request at a time; later ones wait in its queue
    role$.pipe(concatMap((request) => perform(request))),
  ),
);

// verification(request): the verifier's work on one request, busy until it completes
// deadLetter$ hears of an expiry only while toVerifier$ is subscribed
const deadLetter$ = new Subject<unknown>();
const toVerifier$ = request$.pipe(
  // The time to live is set here: each request carries the step after which it is useless.
  map((request) => ({ request, expires: scheduler.now() + timeToLive })),
  // The queue: one request at a time, oldest first, each when the verifier is free.
  concatMap(({ request, expires }) => {
    // The expiry check, made when the request's turn comes, not when it was sent.
    if (scheduler.now() > expires) {
      // An expired request goes to the dead letter channel and never reaches the verifier.
      deadLetter$.next(request);
      return EMPTY;
    }
    // A fresh request reaches the verifier on the next step and keeps it busy until verified.
    return concat(of(request).pipe(delay(1)), verification(request));
  }),
);

// Illustrative: the store's point is an archive that outlives the streams and answers questions after they end, which one marble run cannot show.
// the copy channel: it keeps nothing, so a copy sent while the store is not listening is lost
copies$ = new Subject<Copy>();

handed$ = evidence$.pipe(
  // the fire-and-forget copy: only the envelope
  tap((evidence) => copies$.next(envelopeOf(evidence))),
);
filed$ = report$.pipe(
  // the fire-and-forget copy: the whole report
  tap((report) => copies$.next(report)),
);

entries$ = copies$.pipe(
  // next would run the store at once; this moves its work after the hand-over
  observeOn(asapScheduler),
  // the message store: append each copy that arrives
  scan((entries, copy) => [...entries, copy], [] as readonly Copy[]),
  // the store's entries, kept for whoever asks later
  shareReplay(1),
);

answer$ = entries$.pipe(
  // the query: answered from the store alone, never from handed$ or filed$
  map((entries) => entriesFor(order, entries)),
);

// records$ is the tool-v0 channel; rows$ is the tool-v1 channel the Tools home reads
rows$ = records$.pipe(
  // the translator: each record becomes one tool-v1 row as it arrives, or is refused
  map((record) => toToolV1(record)),
);

// The manager's inbox: the trigger message and every step's reply.
phrases$ = merge(drive$, outcomes$).pipe(
  // The process instance's state, kept by the manager; fold also decides the next step from it.
  scan(fold, opened),
  // Where the process ends: the final message still goes out, then nothing more is read.
  takeWhile(({ stopped }) => !stopped, true),
  // The command to the step that fold chose.
  map(({ phrase }) => phrase),
  // Pacing only: each command leaves one frame after the reply that called for it.
  delay(1),
);

copies$ = orders$.pipe(
  // delay(1): the topic hands an order on one step after the planner publishes it.
  delay(1),
  // share() is the channel: it copies each order to every subscriber and keeps none.
  share(),
);

const listed$ = closes$.pipe(
  // The list for each close is computed from the siblings declared at that moment.
  withLatestFrom(declared$),
  map(([close, declared]) => ({ close, to: recipientsOf(close, declared) })),
  // The copies go out one step after the close arrives.
  delay(1),
  // One list per close, however many channels read it.
  share(),
);
// The list is recorded with the dispatch, an empty one included.
const record$ = listed$.pipe(
  map(({ close, to }) => ({ order: close.order, refreshed: to.join(', ') || 'none' })),
);
// Each recipient on the list gets its own copy of the close.
const copyFor = (sibling: string) =>
  listed$.pipe(
    filter(({ to }) => to.includes(sibling)),
    map(({ close }) => ({ ...close })),
  );
const toA$ = copyFor('A');
const toB$ = copyFor('B');
const toC$ = copyFor('C');

// Illustrative: Request-Reply is an exchange between two parties over two channels, not a transformation of one stream, so this sketch does not run.
const reply$ = replies$.pipe(
  // The reply channel is replies$: receipts are skipped, and any result counts as the reply.
  filter(isResult),
  // The wait: the requestor takes one reply, then stops listening.
  first(),
  // The deadline: no reply in time is an error, and the error is the timeout path.
  timeout({ first: deadline }),
);

// Asynchronous callback: listen on the reply channel, send on the request channel, carry on.
reply$.subscribe({ next: resume, error: takeTimeoutPath });
requests$.next(command);

// Synchronous block, the other choice: listen, send, then stop until the reply or the deadline.
const pending = firstValueFrom(reply$);
requests$.next(command);
const result = await pending;

inOrder$ = bus$.pipe(
  // Buffer: hold each early event; release takes out only the unbroken run from next.
  scan(({ next, held }, event) => release(next, [...held, event]), start),
  // Release: send that run on, one event after another, in sequence order.
  concatMap(({ released }) => released),
  // The run goes on one frame after the event that completed it.
  delay(1),
);
